files.content:
html {
  block-size: 100%;
}

body {
  max-inline-size: 60em;
  min-block-size: 100%;
  margin: 0 auto;
  font-family: 'Open Sans', sans-serif;
  font-size: 16px;
}

.gallery {
  grid-auto-columns: 1fr;
  grid-auto-flow: column;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-template-rows: repeat(3, 1fr);
  grid-auto-rows: 100px 1fr;
  gap: 1em;
  min-block-size: calc(100vh - 4.5em);
}

.radio {
  display: flex;
  align-items: center;
  gap: 1em;
  cursor: pointer;
}

.radio__box {
  inline-size: 27px;
  block-size: 27px;
  accent-color: #000;
}

.radio__box:focus {
  outline: 2px solid #000;
  outline-offset: 0;
}

.gallery-form {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1.5em 0;
}

.gallery__image {
  display: none;
  inline-size: 100%;
  max-inline-size: 100%;
  block-size: 100%;
  max-block-size: 100%;
  object-fit: cover;
}

.gallery__image_selected {
  display: block;
}
